1: // What: the renderer's one navigation state machine and its status priority.
2: // Why: a reload, a late session event, and a screen change must land in one place, not in scattered state.
3: // Removed: two states could disagree about consent or which screen is open, and the urgent message could be hidden.
4: import type {
5:   PulseSample,
6:   ReportResult,
7:   ValidationMessage,
8: } from './contracts.js';
9: import { CONFIDENCE_FLOOR } from './sensing.js';
