11: /** The screens in the §3.1 diagram. `setup`, `sessions` and `help` are filled in by later W4 steps. */
12: export const SCREENS = [
13:   'home',
14:   'setup',
15:   'sensing',
16:   'stopped',
17:   'games',
18:   'review',
19:   'sessions',
20:   'help',
21: ] as const;
22: 
23: export type Screen = (typeof SCREENS)[number];
24: export type FlowTone = 'error' | 'note' | 'default';
25: 
26: export interface ActiveSessionState {
27:   id: string;
28:   startedAtEpochMs: number;
29:   betweenGames: boolean;
30:   /** Player-marked game boundaries in this session. The app never infers one. */
31:   markedGames: number;
32: }
33: 
34: export interface ReviewState {
35:   sessionId: string;
36:   result: ReportResult | null;
37:   building: boolean;
38:   error: string | null;
39:   progress: { scored: number; total: number } | null;
40:   cancelling: boolean;
41: }
