43: export interface FlowState {
44:   screen: Screen;
45:   consent: boolean;
46:   session: ActiveSessionState | null;
47:   stoppedSessionId: string | null;
48:   /** The paste survives Games -> Review -> Games. It is cleared only by a new session. */
49:   draft: string[];
50:   review: ReviewState | null;
51:   explainerSeen: boolean;
52:   notice: string;
53:   error: string | null;
54:   sdkError: string | null;
55: }
