57: export type FlowEvent =
58:   | {
59:       type: 'hydrated';
60:       consent: boolean;
61:       session: { id: string; startedAtEpochMs: number; betweenGames: boolean } | null;
62:       explainerSeen: boolean;
63:     }
64:   | { type: 'explainerDismissed' }
65:   | { type: 'consentChanged'; granted: boolean }
66:   | { type: 'sessionStarted'; sessionId: string; startedAtEpochMs: number }
67:   | { type: 'sessionStopped'; sessionId: string; notice: string }
68:   | { type: 'openHome' }
69:   | { type: 'openSetup' }
70:   | { type: 'openSessions' }
71:   | { type: 'openHelp' }
72:   | { type: 'openStopped' }
73:   | { type: 'openGames' }
74:   | { type: 'openReview' }
75:   | { type: 'pasteChanged'; slots: string[] }
76:   | { type: 'reportStarted'; sessionId: string; slots: string[] }
77:   | { type: 'reportProgress'; scored: number; total: number }
78:   | { type: 'reportReady'; result: ReportResult }
79:   | { type: 'reportFailed'; message: string }
80:   | { type: 'reportCancelRequested' }
81:   | { type: 'reportCancelRejected' }
82:   | { type: 'gapChanged'; betweenGames: boolean }
83:   | { type: 'openedSession'; sessionId: string; report: ReportResult | null; games: string[] }
84:   | { type: 'sessionDeleted'; sessionId: string }
85:   | { type: 'notice'; message: string }
86:   | { type: 'error'; message: string }
87:   | { type: 'sdkError'; message: string }
88:   | { type: 'clearSdkError' }
89:   | { type: 'clearError' };
