122: /**
123:  * Applies one event. A transition the diagram does not allow returns the same object, so no caller
124:  * can create a screen the state machine does not recognise.
125:  */
126: export function flowReducer(state: FlowState, event: FlowEvent): FlowState {
127:   switch (event.type) {
128:     case 'hydrated': {
129:       if (state.session) return state;
130:       return {
131:         ...state,
132:         consent: event.consent,
133:         session: event.session
134:           ? {
135:               id: event.session.id,
136:               startedAtEpochMs: event.session.startedAtEpochMs,
137:               betweenGames: event.session.betweenGames,
138:               markedGames: 0,
139:             }
140:           : null,
141:         stoppedSessionId: event.session ? null : state.stoppedSessionId,
142:         screen: event.session ? 'sensing' : state.screen,
143:         explainerSeen: event.explainerSeen,
144:         notice: event.session ? 'Waiting for a face.' : consentNotice(event.consent),
145:       };
146:     }
147: 
148:     case 'explainerDismissed':
149:       return state.explainerSeen ? state : { ...state, explainerSeen: true };
150: 
151:     case 'consentChanged':
152:       return {
153:         ...state,
154:         consent: event.granted,
155:         notice: consentNotice(event.granted),
156:       };
157: 
158:     case 'sessionStarted':
159:       return {
160:         ...state,
161:         screen: 'sensing',
162:         session: {
163:           id: event.sessionId,
164:           startedAtEpochMs: event.startedAtEpochMs,
165:           betweenGames: false,
166:           markedGames: 0,
167:         },
168:         stoppedSessionId: null,
169:         draft: [],
170:         review: null,
171:         error: null,
172:         notice: 'Waiting for a face.',
173:       };
174: 
175:     case 'sessionStopped':
176:       return {
177:         ...state,
178:         screen: 'stopped',
179:         session: null,
180:         stoppedSessionId: event.sessionId,
181:         review: null,
182:         notice: event.notice,
183:       };
184: 
185:     case 'openHome':
186:       return { ...state, screen: 'home' };
187: 
188:     case 'openSetup':
189:       return { ...state, screen: 'setup' };
190: 
191:     case 'openSessions':
192:       return { ...state, screen: 'sessions' };
193: 
194:     case 'openHelp':
195:       return { ...state, screen: 'help' };
196: 
197:     case 'openStopped':
198:       if (!state.stoppedSessionId) return state;
199:       return { ...state, screen: 'stopped' };
200: 
201:     case 'openGames':
202:       if (state.screen !== 'stopped' && state.screen !== 'review') return state;
203:       if (!currentSessionId(state)) return state;
204:       return { ...state, screen: 'games' };
205: 
206:     case 'openReview':
207:       if (state.screen !== 'stopped') return state;
208:       if (!state.review?.result) return state;
209:       return { ...state, screen: 'review' };
210: 
211:     case 'pasteChanged':
212:       return { ...state, draft: event.slots };
213: 
214:     case 'reportStarted':
215:       return {
216:         ...state,
217:         screen: 'review',
218:         draft: event.slots,
219:         review: {
220:           sessionId: event.sessionId,
221:           result: null,
222:           building: true,
223:           error: null,
224:           progress: null,
225:           cancelling: false,
226:         },
227:       };
228: 
229:     case 'reportProgress':
230:       if (!state.review?.building) return state;
231:       return {
232:         ...state,
233:         review: { ...state.review, progress: { scored: event.scored, total: event.total } },
234:       };
235: 
236:     case 'reportReady':
237:       if (!state.review) return state;
238:       return {
239:         ...state,
240:         review: {
241:           ...state.review,
242:           result: event.result,
243:           building: false,
244:           error: null,
245:           progress: null,
246:           cancelling: false,
247:         },
248:       };
249: 
250:     case 'reportFailed':
251:       if (!state.review) return state;
252:       return {
253:         ...state,
254:         review: {
255:           ...state.review,
256:           building: false,
257:           error: event.message,
258:           progress: null,
259:           cancelling: false,
260:         },
261:       };
262: 
263:     case 'reportCancelRequested':
264:       if (!state.review?.building || state.review.cancelling) return state;
265:       return { ...state, review: { ...state.review, cancelling: true } };
266: 
267:     case 'reportCancelRejected':
268:       if (!state.review) return state;
269:       return { ...state, review: { ...state.review, cancelling: false } };
270: 
271:     case 'gapChanged': {
272:       const session = activeSession(state);
273:       if (!session) return state;
274:       const markedGames = session.markedGames + (event.betweenGames && !session.betweenGames ? 1 : 0);
275:       return {
276:         ...state,
277:         session: { ...session, betweenGames: event.betweenGames, markedGames },
278:       };
279:     }
280: 
281:     case 'openedSession':
282:       return {
283:         ...state,
284:         screen: event.report ? 'review' : 'games',
285:         session: null,
286:         stoppedSessionId: event.sessionId,
287:         draft: event.games,
288:         review: event.report
289:           ? {
290:               sessionId: event.sessionId,
291:               result: event.report,
292:               building: false,
293:               error: null,
294:               progress: null,
295:               cancelling: false,
296:             }
297:           : null,
298:         error: null,
299:       };
300: 
301:     case 'sessionDeleted':
302:       if (state.stoppedSessionId !== event.sessionId && state.review?.sessionId !== event.sessionId) {
303:         return state;
304:       }
305:       return {
306:         ...state,
307:         screen: 'home',
308:         stoppedSessionId: null,
309:         draft: [],
310:         review: null,
311:         notice: 'Session deleted.',
312:       };
313: 
314:     case 'notice':
315:       return { ...state, notice: event.message };
316: 
317:     case 'error':
318:       return { ...state, error: event.message };
319: 
320:     case 'sdkError':
321:       return { ...state, sdkError: event.message };
322: 
323:     case 'clearSdkError':
324:       return state.sdkError === null ? state : { ...state, sdkError: null };
325: 
326:     case 'clearError':
327:       return { ...state, error: null };
328:   }
329: }
