331: export interface StatusInput {
332:   error: string | null;
333:   sdkError: string | null;
334:   screen: Screen;
335:   hint: string | null;
336:   notice: string;
337: }
338: 
339: export interface StatusLine {
340:   text: string;
341:   tone: FlowTone;
342:   urgent: boolean;
343: }
344: 
345: /**
346:  * One status region. An operation error outranks a sensing error, which outranks a live hint; the
347:  * session note is last. Nothing here is written by a screen that happens to render later.
348:  */
349: export function statusFor(input: StatusInput): StatusLine {
350:   if (input.error) return { text: input.error, tone: 'error', urgent: true };
351:   if (input.sdkError) return { text: input.sdkError, tone: 'error', urgent: true };
352:   if (input.screen === 'sensing' && input.hint) {
353:     return { text: input.hint, tone: 'note', urgent: false };
354:   }
355:   return { text: input.notice, tone: 'default', urgent: false };
356: }
357: 
358: /** The live sensing sentence, or null when the trace is already strong enough. */
359: export function sensingHint(
360:   samples: readonly PulseSample[],
361:   validation: ValidationMessage | null,
362: ): string | null {
363:   if (validation && validation.code !== 0) return validation.hint;
364:   if (samples.length === 0) return 'Waiting for a face.';
365:   const latest = samples[samples.length - 1];
366:   if (!latest.stable || latest.confidence < CONFIDENCE_FLOOR) {
367:     return samples.some((sample) => sample.stable && sample.confidence >= CONFIDENCE_FLOOR)
368:       ? 'Low confidence.'
369:       : 'Validating.';
370:   }
371:   return null;
372: }

