339: export interface StatusLine {
340:   text: string;
341:   tone: FlowTone;
342:   urgent: boolean;
343: }
344: 
345: /**
346:  * One status region. An operation error outranks a sensing error, which outranks a live hint; the
347:  * session note is last. Nothing here is written by a screen that happens to render later.
348:  */
349: export function statusFor(input: StatusInput): StatusLine {
350:   if (input.error) return { text: input.error, tone: 'error', urgent: true };
351:   if (input.sdkError) return { text: input.sdkError, tone: 'error', urgent: true };
352:   if (input.screen === 'sensing' && input.hint) {
353:     return { text: input.hint, tone: 'note', urgent: false };
354:   }
355:   return { text: input.notice, tone: 'default', urgent: false };
356: }
