162:   sink: ((samples: readonly PulseSample[]) => void) | undefined,
163: ): void {
164:   const key = path.resolve(root);
165:   if (sink) sampleSinks.set(key, sink);
166:   else sampleSinks.delete(key);
167: }
168: 
169: export async function stopSession(
170:   root: string,
171:   stopAnchor: SessionAnchor,
172:   reason: SessionStopReason,
173: ): Promise<SessionMeta> {
174:   const key = path.resolve(root);
175:   const current = active.get(key);
176:   if (!current) throw new Error('No session is running.');
177:   if (current.state === 'starting') {
178:     current.state = 'stopping';
179:     current.stopRequest = { anchor: stopAnchor, reason };
180:     return current.stopped;
181:   }
182:   const sessionId = current.id;
183:   if (!sessionId) throw new Error('No session is running.');
184:   if (current.state === 'running') current.state = 'stopping';
185:   else if (current.state !== 'stopping') throw new Error('No session is running.');
186:   return beginStop(root, key, current, sessionId, stopAnchor, reason);
187: }
188: 
189: function beginStop(
190:   root: string,
191:   key: string,
192:   current: ActiveSession,
193:   sessionId: string,
194:   stopAnchor: SessionAnchor,
195:   reason: SessionStopReason,
196: ): Promise<SessionMeta> {
197:   if (current.finishStop) return current.finishStop;
198:   const run = (async () => {
199:     try {
200:       await current.ingest;
201:       const meta = await readMeta(root, sessionId);
202:       const saved = await finalize(root, meta, stopAnchor, reason);
203:       clearLimitTimer(current);
204:       if (active.get(key) === current) active.delete(key);
205:       return saved;
206:     } catch (error) {
207:       clearLimitTimer(current);
208:       current.finishStop = undefined;
209:       throw error;
210:     }
211:   })();
212:   current.finishStop = run;
213:   return run;
214: }
215: 
216: export interface SessionRecoveryFailure {
217:   id: string;
218:   message: string;
219: }
220: 
221: export async function recoverInterruptedSessions(root: string): Promise<{
222:   recovered: SessionMeta[];
223:   failures: SessionRecoveryFailure[];
224: }> {
225:   const ids = await listSessions(root);
226:   const recovered: SessionMeta[] = [];
227:   const failures: SessionRecoveryFailure[] = [];
228:   for (const id of ids) {
229:     try {
230:       const meta = await readMeta(root, id);
231:       if (meta.stopReason) continue;
232:       const samples = await readSamples(root, id);
233:       const lastUs = samples.reduce((max, sample) => Math.max(max, sample.tUs), meta.startAnchor.monoUs);
234:       const stopAnchor = {
235:         monoUs: lastUs,
236:         epochMs: meta.startAnchor.epochMs + Math.round((lastUs - meta.startAnchor.monoUs) / 1000),
237:       };
238:       recovered.push(await finalize(root, meta, stopAnchor, 'crash'));
239:     } catch (error) {
240:       failures.push({
241:         id,
242:         message: error instanceof Error ? error.message : 'The session could not be recovered.',
243:       });
244:     }
245:   }
246:   const key = path.resolve(root);
247:   const current = active.get(key);
248:   if (current && recovered.some((meta) => meta.id === current.id)) active.delete(key);
249:   return { recovered, failures };
250: }
251: 
252: async function finalize(
253:   root: string,
254:   meta: SessionMeta,
255:   stopAnchor: SessionAnchor,
256:   reason: NonNullable<SessionMeta['stopReason']>,
257: ): Promise<SessionMeta> {
258:   const samples = await readSamples(root, meta.id);
259:   const baseline = baselineFromSamples(samples, meta.startAnchor.monoUs);
260:   const coverage = coverageFromSamples(samples, meta.startAnchor.monoUs, stopAnchor.monoUs);
261:   await saveMeta(root, {
262:     ...meta,
263:     ...baseline,
264:     stopAnchor,
265:     stopReason: reason,
266:     coverage,
267:   });
268:   return readMeta(root, meta.id);
269: }
270: 
271: export function activeTimeControl(root: string): string | undefined {
272:   return active.get(path.resolve(root))?.timeControl;
273: }
274: 
275: export function hasActiveSession(root: string): boolean {
276:   return active.has(path.resolve(root));
277: }
278: 
279: export interface ActiveSessionState {
280:   active: boolean;
281:   sessionId: string | null;
282:   startedAtEpochMs: number | null;
283: }
