285: /**
286:  * What a reloaded page may adopt. A session that is still starting or already stopping has no
287:  * stable id for the page, so it is reported closed and the page starts at Home.
288:  */
289: export function activeSessionState(root: string): ActiveSessionState {
290:   const current = active.get(path.resolve(root));
291:   if (!current || current.state !== 'running' || !current.id) {
292:     return { active: false, sessionId: null, startedAtEpochMs: null };
293:   }
294:   return {
295:     active: true,
296:     sessionId: current.id,
297:     startedAtEpochMs: current.startedAtEpochMs,
298:   };
299: }
300: 
301: /** True only while this exact id is the active, running session. */
302: export function isActiveSession(root: string, sessionId: string): boolean {
303:   const current = active.get(path.resolve(root));
304:   return current?.state === 'running' && current.id === sessionId;
305: }
306: 
307: function reserve(
308:   anchor: SessionAnchor,
309:   timeControl: string,
310:   limitScheduler: SessionLimitScheduler,
311: ): ActiveSession {
312:   let resolveStopped: (meta: SessionMeta) => void = () => undefined;
313:   let rejectStopped: (error: unknown) => void = () => undefined;
314:   const stopped = new Promise<SessionMeta>((resolve, reject) => {
315:     resolveStopped = resolve;
316:     rejectStopped = reject;
317:   });
318:   stopped.catch(() => undefined);
319:   return {
320:     anchor,
321:     startedAtEpochMs: anchor.epochMs,
322:     timeControl,
323:     state: 'starting',
324:     ingest: Promise.resolve(),
325:     stopped,
326:     resolveStopped,
327:     rejectStopped,
328:     limitScheduler,
329:   };
330: }
331: 
332: function armLimitTimer(key: string, current: ActiveSession, onLimit: (() => void) | undefined): void {
333:   current.limitTimer = current.limitScheduler.set(() => {
334:     current.limitTimer = undefined;
335:     if (active.get(key) !== current || current.state !== 'running') return;
336:     try {
337:       onLimit?.();
338:     } catch {
339:       // The next explicit stop still closes the session; a timer callback must not crash main.
340:     }
341:   }, MAX_SESSION_US / 1000);
342: }
343: 
344: function clearLimitTimer(current: ActiveSession): void {
345:   if (current.limitTimer === undefined) return;
346:   current.limitScheduler.clear(current.limitTimer);
347:   current.limitTimer = undefined;
348: }
