350: async function commitSamples(root: string, sessionId: string, samples: readonly PulseSample[]): Promise<void> {
351:   await appendSamples(root, sessionId, samples);
352:   try {
353:     sampleSinks.get(path.resolve(root))?.(samples);
354:   } catch {
355:     // The batch is already in the file. The caller must not treat this as a reason to append it again.
356:   }
357: }
358: 
359: function snapshotSamples(samples: readonly PulseSample[]): PulseSample[] {
360:   return samples.map((sample) => ({
361:     tUs: sample.tUs,
362:     bpm: sample.bpm,
363:     confidence: sample.confidence,
364:     stable: sample.stable,
365:   }));
366: }
367: 
368: function requireActive(root: string): ActiveSession & { id: string } {
369:   const current = active.get(path.resolve(root));
370:   if (!current || current.state !== 'running' || !current.id) throw new Error('No session is running.');
371:   return current as ActiveSession & { id: string };
372: }
